def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = defaultdict(set)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                points[grid[r][c]].add((r, c))

    out = [row[:] for row in grid]
    for color, cells in points.items():
        for r, c in cells:
            for dr, dc in ((1, 1), (1, -1)):
                # Only start at one end of a matching diagonal pair.
                if (r + dr, c + dc) not in cells:
                    continue
                # Extend from the far end of the pair.
                rr, cc = r + dr, c + dc
                while (rr + dr, cc + dc) in cells:
                    rr += dr
                    cc += dc
                rr += dr
                cc += dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr += dr
                    cc += dc

                # Extend outward from the opposite end.
                rr, cc = r - dr, c - dc
                while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                    out[rr][cc] = color
                    rr -= dr
                    cc -= dc
    return out
